            interior = [[grid[r][c] == color for c in range(c0+1, c1)]
                        for r in range(r0+1, r1)]
            count = sum(sum(row) for row in interior)
            frames.append((color, r0, r1, c0, c1, interior, count))
    if not frames:
        return [row[:] for row in grid]
    # The frame containing the densest interior motif is the pattern source.
    source = max(frames, key=lambda f: f[6])
    pattern = source[5]
    out = [row[:] for row in grid]
    for frame in frames:
        color, r0, r1, c0, c1, interior, count = frame
        if frame is source or count != 0:
            continue
        for dr in range(min(len(pattern), r1-r0-1)):
            for dc in range(min(len(pattern[0]), c1-c0-1)):
                if pattern[dr][dc]:
                    out[r0+1+dr][c0+1+dc] = color
    return out
